// @spec openspec/specs/branch/branch-row/spec.md
// @spec openspec/specs/repository/outgoing/spec.md
// @spec openspec/specs/branch/patronus/spec.md
// A copy whose sync merged a generated file by words (`resolved_words_generated`: the commit of ui changes the header-
// marked `generated/limits.js` on the line core changed first, and the words resolve it): the Status cell says what it
// needs to land, the push asks first and pushes once accepted, and a commit of ui that writes the file clears the mark
import { test, expect } from "../fixtures/test-fixtures"
import { expandBranch, findBranchRow, getBranchDetailsRow, getPushButton } from "../helpers/branch-helpers"
import { availableRobots } from "../helpers/patronus-helpers"
import { expectPushedToRemote, remotePushes } from "../helpers/push-helpers"
import { popoverStart, safePushPopover, slotSafePush } from "../helpers/safe-push-helpers"
import { runAndWaitForAnswer, syncFromMenu } from "../helpers/sync-helpers"
import { openTooltip, waitForStepFacts } from "../helpers/wait-helpers"

test.describe("A generated file merged by words", () => {
  test("should mark a branch whose copy merged a generated file by words and ask before its push", async ({ page, setupRepo, syncAndWaitForBranches }) => {
    const repo = await setupRepo("resolved_words_generated")
    await syncAndWaitForBranches()
    const row = findBranchRow(page, "ui")
    const status = row.getByTestId("branch-status")
    await expect(status).toHaveText("regenerate limits.js")
    // its hover names the file, why it is generated, the commit the copy lacks and the fix
    await status.hover()
    const tooltip = openTooltip(page)
    await expect(tooltip).toContainText(
      "generated/limits.js (Generated by tools/limits.mjs; edit limits.json) was merged by words in the copy of “Retry three times and log it”, not written by its generator; the copy lacks “Raise the timeout” of core.",
    )
    await expect(tooltip).toContainText("Stack ui on core to land it too.")
    // core's copy is clean: nothing to regenerate
    await expect(findBranchRow(page, "core").getByTestId("branch-status")).not.toHaveText(/regenerate/)
    // Resolved by Words of the commit names the generated file
    if ((await row.getAttribute("data-state")) !== "open") {
      await expandBranch(page, row)
    }
    await getBranchDetailsRow(page, "ui").getByTestId("resolved-by-words-notice").click()
    await expect(getBranchDetailsRow(page, "ui").getByTestId("resolved-by-words-generated")).toHaveText(
      "generated/limits.js is generated (Generated by tools/limits.mjs; edit limits.json): the words merged its text, not its generator. The branch says “regenerate” while its copy holds this merge.",
    )

    // the click asks first, naming the file; nothing is pushed until Push Anyway
    await getPushButton(row).click()
    const description = page.getByTestId("push-description").filter({ has: page.getByTestId("push-confirm") })
    await expect(description.getByTestId("push-regenerate")).toContainText("generated/limits.js (Generated by tools/limits.mjs; edit limits.json) was merged by words")
    expect(await remotePushes(repo)).toEqual([])
    const confirm = description.getByTestId("push-confirm")
    await expect(confirm).toHaveText("Push Anyway")
    await runAndWaitForAnswer(page, "execute", () => confirm.click())
    await expectPushedToRemote(repo, ["ui"])
    expect(await remotePushes(repo)).toEqual([["ui"]])

    // a commit of ui that writes the file: its copy no longer holds what the words wrote, and the push asks nothing
    await repo.commit(
      "(ui) Regenerate the limits",
      {
        "generated/limits.js":
          '// Generated by tools/limits.mjs; edit limits.json\nexport const host = "localhost"\nexport const limits = { timeout: 30, retries: 3 }\nexport const port = 8080\nexport const name = "limits"\nexport const verbose = true\nexport const regenerated = true\n',
      },
      1704123000,
    )
    await syncFromMenu(page)
    await expect(status).not.toHaveText(/regenerate/)
    await runAndWaitForAnswer(page, "execute", () => getPushButton(row).click())
    await expect(page.getByTestId("push-confirm")).toHaveCount(0)
    expect(await remotePushes(repo)).toEqual([["ui"], ["ui"]])
  })

  test("should ask before a Safe Push of a copy with a generated file merged by words, and start once accepted", async ({ page, setupRepo, syncAndWaitForBranches }) => {
    const repo = await setupRepo("resolved_words_generated", { patronus: availableRobots() })
    await syncAndWaitForBranches()
    await waitForStepFacts(findBranchRow(page, "ui").getByTestId("next-step-slot"))
    await slotSafePush(page, "ui").click()
    const popover = safePushPopover(page)
    await expect(popover).toHaveAttribute("data-decision", "confirm")
    await expect(popover.getByTestId("safe-push-regenerate")).toContainText(
      "generated/limits.js (Generated by tools/limits.mjs; edit limits.json) was merged by words in the copy of “Retry three times and log it”",
    )
    expect((await repo.getPatronusLog()).starts).toEqual([])
    await runAndWaitForAnswer(page, "execute", () => popoverStart(page).click())
    expect((await repo.getPatronusLog()).starts).toHaveLength(1)
  })
})
